                const matches = ownerIdsForCondition.flatMap(pid => [ ...(this.zones[pid]?.battleArea || []), ...(this.zones[pid]?.breedingArea || []) ])
                    .filter(c => this.cardMatchesTarget(c, lookupTarget));
