                const target = condition.target || condition.card || { cardType: 'option' };
                const count = rows.filter(row => this.cardMatchesTarget(row.card || row, { ...target, cardType: target.cardType || 'option' })).length;
                if (condition.value !== undefined || condition.operator) return cmp(count, condition.value ?? 0);
